local TongMaker = {}
local PRODUCTS = {
    iron_tong = { name = "Železne kovinarske klešče", ironCost = 5, woodCost = 1, leatherCost = 1, time = 6, cost = 200, prestige = 4, happiness = 2, description = "Železne kovinarske klešče za prijemanje vroče kovine." },
    bronze_tong = { name = "Bronaste kovinarske klešče", bronzeCost = 5, ironCost = 1, woodCost = 1, leatherCost = 1, time = 8, cost = 480, prestige = 6, happiness = 3, description = "Bronaste kovinarske klešče za fino kovaštvo." },
    silver_tong = { name = "Srebrne kovinarske klešče", silverCost = 5, bronzeCost = 1, ironCost = 1, woodCost = 1, leatherCost = 1, time = 12, cost = 1150, prestige = 11, happiness = 4, description = "Srebrne kovinarske klešče za plemiške kovače." },
    gilded_tong = { name = "Pozlačene kovinarske klešče", goldCost = 1, silverCost = 5, bronzeCost = 1, woodCost = 1, leatherCost = 1, time = 16, cost = 2480, prestige = 20, happiness = 5, description = "Pozlačene kovinarske klešče za dvorne kovače." },
    jewel_set_tong = { name = "Draguljaste kovinarske klešče", goldCost = 2, silverCost = 5, jewelCost = 1, bronzeCost = 1, woodCost = 1, leatherCost = 1, time = 20, cost = 5300, prestige = 36, happiness = 7, description = "Draguljaste kovinarske klešče za kraljevske kovače." },
    royal_sovereign_tong = { name = "Kraljevski suverene kovinarske klešče", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 27, cost = 11300, prestige = 70, happiness = 13, description = "Suverene kovinarske klešče z biseri za krono." },
}
local BUILDINGS = {
    tong_workshop = { name = "Kleščna delavnica", cost = { gold = 380, wood = 175, stone = 155, iron = 11 }, upkeep = 7, qualityBonus = 5 },
    tong_house = { name = "Kleščna hiša", cost = { gold = 1310, wood = 360, stone = 295, silver = 8, iron = 9 }, upkeep = 28, qualityBonus = 18 },
    master_tong_atelier = { name = "Mojstrski kleščni atelje", cost = { gold = 3230, wood = 420, stone = 550, silver = 40, gold = 8 }, upkeep = 76, qualityBonus = 30 },
    sovereign_tong_palace = { name = "Suverena kleščna palača", cost = { gold = 13800, wood = 655, stone = 870, gold = 89, jewel = 20 }, upkeep = 264, qualityBonus = 55, prestigeBonus = 50 },
}
TongMaker.ironStock = 18; TongMaker.bronzeStock = 14; TongMaker.woodStock = 10; TongMaker.leatherStock = 10; TongMaker.silverStock = 8; TongMaker.goldStock = 6; TongMaker.jewelStock = 4; TongMaker.pearlStock = 4
TongMaker.productStock = {}; TongMaker.buildings = {}; TongMaker.maker = nil; TongMaker.activeMaking = {}; TongMaker.totalProducts = 0; TongMaker.dayTimer = 0
function TongMaker.init() TongMaker.ironStock=18; TongMaker.bronzeStock=14; TongMaker.woodStock=10; TongMaker.leatherStock=10; TongMaker.silverStock=8; TongMaker.goldStock=6; TongMaker.jewelStock=4; TongMaker.pearlStock=4; TongMaker.productStock={}; TongMaker.buildings={}; TongMaker.maker=nil; TongMaker.activeMaking={}; TongMaker.totalProducts=0; TongMaker.dayTimer=0; print("[TongMaker] Royal Tong Maker System initialized (6 products, 4 buildings)") end
function TongMaker.hireMaker(n,s) s=s or math.random(55,90); local c=590+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; TongMaker.maker={name=n or ("Kleščar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kleščar najet: %s (spretnost: %d)",TongMaker.maker.name,s),"success") end; return true end
function TongMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function TongMaker.build(id) local ok,e=TongMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(TongMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function TongMaker.getQualityBonus() local b=0; for _,bd in ipairs(TongMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function TongMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and TongMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and TongMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and TongMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and TongMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and TongMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and TongMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and TongMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and TongMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #TongMaker.buildings==0 then return false,"Potrebna kleščna delavnica" end; if not TongMaker.maker then return false,"Potreben kleščar" end; return true end
function TongMaker.make(pt,qty) qty=qty or 1; local ok,e=TongMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then TongMaker.ironStock=TongMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then TongMaker.bronzeStock=TongMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then TongMaker.woodStock=TongMaker.woodStock-d.woodCost*qty end; if d.leatherCost then TongMaker.leatherStock=TongMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then TongMaker.silverStock=TongMaker.silverStock-d.silverCost*qty end; if d.goldCost then TongMaker.goldStock=TongMaker.goldStock-d.goldCost*qty end; if d.jewelCost then TongMaker.jewelStock=TongMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then TongMaker.pearlStock=TongMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if TongMaker.maker then t=math.max(1,t-math.floor(TongMaker.maker.skill/13)) end; table.insert(TongMaker.activeMaking,{id="tong_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function TongMaker.completeMaking(m) local q=1.0+(TongMaker.getQualityBonus()/100); if TongMaker.maker then q=q+(TongMaker.maker.skill/140) end; q=math.min(2.5,q); TongMaker.productStock[m.productType]=(TongMaker.productStock[m.productType] or 0)+m.quantity; TongMaker.totalProducts=TongMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if TongMaker.maker then TongMaker.maker.itemsMade=TongMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then TongMaker.maker.skill=math.min(100,TongMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Klešče izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"tong.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function TongMaker.update(dt) if not _G.state then return end; TongMaker.dayTimer=TongMaker.dayTimer+dt; if TongMaker.dayTimer>=30 then TongMaker.dayTimer=0; for i=#TongMaker.activeMaking,1,-1 do local m=TongMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then TongMaker.completeMaking(m); table.remove(TongMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(TongMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if TongMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function TongMaker.getStats() return {ironStock=TongMaker.ironStock,bronzeStock=TongMaker.bronzeStock,woodStock=TongMaker.woodStock,leatherStock=TongMaker.leatherStock,silverStock=TongMaker.silverStock,goldStock=TongMaker.goldStock,jewelStock=TongMaker.jewelStock,pearlStock=TongMaker.pearlStock,productStock=TongMaker.productStock,numBuildings=#TongMaker.buildings,hasMaker=TongMaker.maker~=nil,makerName=TongMaker.maker and TongMaker.maker.name or "—",makerSkill=TongMaker.maker and TongMaker.maker.skill or 0,activeMaking=#TongMaker.activeMaking,totalProducts=TongMaker.totalProducts} end
return TongMaker
